import pytest
from concurrent.futures import ThreadPoolExecutor


def square(x: int) -> int:
    return x * x


def sum_squares_with(xs: list[int], workers: int) -> int:
    """Sum of squares of xs, computing each square via square() in a
    thread pool of `workers` threads. The result is independent of
    `workers`. Raises ValueError if workers < 1."""
    if workers < 1:
        raise ValueError("workers must be >= 1")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        squares = list(pool.map(square, xs))
    return sum(squares)


def sum_squares(xs: list[int]) -> int:
    """Sum of squares of every element of xs (0 for an empty list),
    computing the squares in parallel in a thread pool."""
    return sum_squares_with(xs, 4)


WORKER_COUNTS = [1, 2, 3, 4, 8, 32]


def test_sum_squares_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14
    assert sum_squares([]) == 0
    assert sum_squares([-4]) == 16
    assert sum_squares([-1, 1, 0]) == 2


def test_sum_squares_large_ints() -> None:
    big = 10**20
    assert sum_squares([big, -big]) == 2 * big * big


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_same_result_at_every_worker_count(workers: int) -> None:
    xs = list(range(-50, 150))
    expected = sum(square(x) for x in xs)
    assert sum_squares_with(xs, workers) == expected


@pytest.mark.parametrize("workers", WORKER_COUNTS)
def test_more_workers_than_items(workers: int) -> None:
    assert sum_squares_with([3], workers) == 9
    assert sum_squares_with([], workers) == 0


def test_all_worker_counts_agree() -> None:
    xs = [7, -3, 12, 0, 5, 5, -9, 100, 2, 1]
    results = {sum_squares_with(xs, w) for w in WORKER_COUNTS}
    assert results == {sum_squares(xs)}
    assert results == {sum(x * x for x in xs)}


def test_input_not_mutated() -> None:
    xs = [3, -2, 1]
    copy = list(xs)
    sum_squares(xs)
    assert xs == copy


def test_invalid_worker_count() -> None:
    with pytest.raises(ValueError):
        sum_squares_with([1, 2], 0)
    with pytest.raises(ValueError):
        sum_squares_with([1, 2], -1)
